t("sliced", "被切开", "_t")
t("raked", "被抓伤", "_t")
t("disembowelled", "被开膛破肚", "_t")
t("stabbed", "被刺杀", "_t")
t("pierced", "被刺穿", "_t")
t("shattered", "被击碎", "_t")
t("swiped", "被横扫", "_t")
t("mutilated", "被肢解", "_t")
t("skewered", "被刺穿成串", "_t")
t("mauled", "被撕碎", "_t")
t("splattered", "被击成肉泥", "_t")
t("punctured", "被刺穿", "_t")
t("eviscerated", "被掏出内脏", "_t")
t("blasted", "被能量引爆", "_t")
t("burnt", "被烧焦", "_t")
t("scalded", "被烫伤", "_t")
t("slimed", "被黏液覆盖", "_t")
t("splurged", "被黏液溅射", "_t")
t("debilitated by noxious blight before falling", "被剧毒枯萎折磨得虚弱不堪", "_t")
t("tainted", "被污染", "_t")
t("purified", "被净化", "_t")
