section "mod-tome/data/general/traps/elemental.lua"

t("Deals %s%d#LAST# %s damage", "造成%s%d#LAST#%s伤害", "tformat")
t("Deals %s%d#LAST# %s damage (radius %d)", "造成%s%d#LAST# %s伤害(半径 %d)", "tformat")
t("A bolt of fire blasts onto @target@!", "一道火焰击中了@target@！", "_t")
t("crackling spot", "噼啪作响的地点", "_t")
t("A bolt of fire fires onto @target@!", "一团火焰炸向@target@！", "_t")
t("@Target@ is blasted with anti-magic forces!", "@Target@遭到反魔能量轰击！", "_t")
t("Deals up to %d manaburn damage, draining mana, vim, and positive and negative energies within radius %d.", "在%d码范围内最多造成%d点法力燃烧伤害，并吸取法力值、活力值以及正负能量。", "tformat", {2, 1})
t("A powerful blast of fire impacts @target@!", "一团大火球炸向@target@！", "_t")

------------------------------------------------
section "mod-tome/data/general/traps/natural_forest.lua"

t("slippery rock", "湿滑的石块", "_t")
t("A motile vine that strikes out for %s%d#LAST# %s damage.", "一团活动的藤蔓，打击目标造成%s%d#LAST#%s伤害。", "tformat")

------------------------------------------------
section "mod-tome/data/general/traps/teleport.lua"

t("Teleports the victim away.  How does anyone get close enough to disarm this trap...?", "将目标传送走。到底要怎样才能靠近并解除这个陷阱……？", "_t")
t("@Target@ shimmers briefly.", "@Target@短暂地闪烁。", "_t")
t("%s resists being teleported!", "%s 抵抗传送！", "logSeen")

------------------------------------------------
section "mod-tome/data/general/traps/temporal.lua"

t("@Target@ is caught in a distorted pocket of time!", "@Target@被困在扭曲的时间中！", "_t")
t("@Target@ is caught in an extremely distorted pocket of time!", "@Target@被困在极度扭曲的时间中！", "_t")
t("Creates a major temporal anomaly when triggered.", "触发时制造大型时空异常。", "_t")

